{"command": "cat > extract_exif.py << 'EOF'
from PIL import Image
from PIL.ExifTags import TAGS
import json

# Open the image
img = Image.open('sample.jpg')

# Extract EXIF data
exif_data = img._getexif()

if exif_data is None:
    print("No EXIF data found")
    exit(1)

# Convert to readable format and keep raw values
exif_dict = {}
focal_info = {}

for tag_id, value in exif_data.items():
    tag_name = TAGS.get(tag_id, tag_id)
    exif_dict[tag_name] = value

    # Look for focal length related tags
    if 'focal' in str(tag_name).lower():
        focal_info[tag_name] = value
        print(f"{tag_name}: {value} (raw type: {type(value).__name__})")

# Also check for 35mm equivalent in standard EXIF tags
if 'FocalLength' in exif_dict:
    print(f"\nActual Focal Length:")
    print(f"  Tag: FocalLength")
    print(f"  Value: {exif_dict['FocalLength']} mm")

if 'FocalLengthIn35mmFilm' in exif_dict:
    print(f"\n35mm Equivalent Focal Length:")
    print(f"  Tag: FocalLengthIn35mmFilm")
    print(f"  Value: {exif_dict['FocalLengthIn35mmFilm']} mm")
elif 'FocalLengthIn35mmFormat' in exif_dict:
    print(f"\n35mm Equivalent Focal Length:")
    print(f"  Tag: FocalLengthIn35mmFormat")
    print(f"  Value: {exif_dict['FocalLengthIn35mmFormat']} mm")
else:
    print(f"\n35mm Equivalent Focal Length: MISSING")

# Save full EXIF data to JSON
with open('photo-result.json', 'w') as f:
    # Need to handle tuples and other types that aren't JSON serializable
    json_safe_exif = {}
    for key, value in exif_dict.items():
        if isinstance(value, (int, float, str)):
            json_safe_exif[key] = value
        elif isinstance(value, tuple):
            json_safe_exif[key] = value  # tuples will be converted to arrays
        elif isinstance(value, bytes):
            json_safe_exif[key] = value.decode('utf-8', errors='ignore')
        else:
            json_safe_exif[key] = str(value)

    json.dump(json_safe_exif, f, indent=2)

print(f"\nMetadata saved to photo-result.json")
EOF
uv run --offline --no-sync --project /opt/demo python extract_exif.py", "description": "Extract EXIF focal length metadata from sample.jpg"}
